def need(condition, message):
    if not condition:
        raise AssertionError(message)


def read(path):
    return json.loads(path.read_text())


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def lines(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def signature(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'))


def spread(values):
    values = list(values)
    return {'median': stats.median(values), 'range': [min(values), max(values)], 'sum': sum(values)}


def gc_observations(path):
    text = path.read_text()
    need('Using G1' in text, 'G1 must identify itself')
    need(not any(token in text for token in ('System.gc()', 'Diagnostic Command',
                                            'Heap Inspection Initiated GC')), 'No explicit/diagnostic GC')
    ids, pauses, concurrent, kinds = set(), [], [], collections.Counter()
    for line in text.splitlines():
        event = re.search(r'GC\((\d+)\) (.*)', line)
        if event is None:
            continue
        ids.add(int(event.group(1)))
        body = event.group(2)
        elapsed = re.search(r' ([0-9]+(?:\.[0-9]+)?)ms$', body)
        if elapsed:
            if body.startswith('Pause '):
                pauses.append(float(elapsed.group(1)))
                kinds[' '.join(body.split()[:2])] += 1
            elif body.startswith('Concurrent '):
                concurrent.append(float(elapsed.group(1)))
    return {'ids': len(ids), 'pauses': len(pauses), 'pauseMs': sum(pauses),
            'maxPauseMs': max(pauses, default=0), 'completedConcurrentCycles': len(concurrent),
            'concurrentCycleMs': sum(concurrent), 'pauseKinds': dict(kinds)}


